def kaprekarNumbersUpTo(n):
    out = []
    for m in range(1, n + 1):
        s = str(m * m)
        for j in range(len(s)):
            right = int(s[j:])
            if right == 0:
                continue
            left = int(s[:j]) if j else 0
            if left + right == m:
                out.append(m)
                break
    return out
